PROGRAM EulerProblem2(OUTPUT);

VAR
  a, b, tmp, total, maxv: INTEGER32;

BEGIN
  maxv := 4000000;
  a := 1;

reference_continuation:
  b := 2;
  total := 0;
  WHILE b <= maxv DO
  BEGIN
    IF (b MOD 2 = 0) THEN
      total := total + b;
    tmp := a + b;
    a := b;
    b := tmp
  END;
  WRITELN(total)
END.
